def compute(vars):
    net_income = vars["Net Income"]
    sales_revenue = vars["Sales Revenue"]

    output_meta = {
        "currency": None,
        "scale": None,
        "unit": "ratio"
    }
    trace = {
        "Net Income": net_income,
        "Sales Revenue": sales_revenue,
        "input_meta": {
            "Net Income": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            },
            "Sales Revenue": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        },
        "output_meta": output_meta
    }

    if net_income is None or sales_revenue is None or sales_revenue == 0:
        return {
            "value": None,
            "trace": trace
        }

    net_income_margin = net_income / sales_revenue
    trace["Net income margin"] = net_income_margin

    return {
        "value": net_income_margin,
        "trace": trace
    }
